var kanjiLookup = func() map[rune]uint16 {
	m := make(map[rune]uint16, len(kanjiValues))
	i := 0
	for _, r := range kanjiRunes {
		m[r] = kanjiValues[i]
		i++
	}
	return m
}()

// kanjiCode returns the 13-bit QR code for a JIS X 0208 character.
func kanjiCode(r rune) (int, bool) {
	v, ok := kanjiLookup[r]
	return int(v), ok
}
